import{_ as s,o as a,c as i,a2 as t}from"./chunks/framework.LX5S0jbT.js";const k=JSON.parse('{"title":"Pi Packages","description":"","frontmatter":{},"headers":[],"relativePath":"packages.md","filePath":"packages.md"}'),n={name:"packages.md"};function o(p,e,l,r,d,c){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="pi-packages" tabindex="-1">Pi Packages <a class="header-anchor" href="#pi-packages" aria-label="Permalink to &quot;Pi Packages&quot;">​</a></h1><p>Pi packages install and distribute extensions, skills, prompt templates, and themes as one unit. Use a package when a customization should be shared through npm or git, or when several resources belong together.</p><p>A package is an ordinary directory or npm package. It can expose conventional resource directories, declare explicit paths under the <code>pi</code> key in <code>package.json</code>, and carry its own runtime dependencies.</p><h2 id="install-and-manage-packages" tabindex="-1">Install and manage packages <a class="header-anchor" href="#install-and-manage-packages" aria-label="Permalink to &quot;Install and manage packages&quot;">​</a></h2><p>Install from npm, git, or a local path:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm:@example/pi-tools@1.0.0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git:github.com/example/pi-tools@v1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./local-package</span></span></code></pre></div><p><code>pi list</code> shows configured packages. Use <code>pi remove &lt;source&gt;</code> to remove one and <code>pi update --extensions</code> to reconcile package installations. See <a href="./cli.html#package-commands">Command Line</a> for every package command and option.</p><p>If a configured package fails to install at startup, for example because npm cannot reach the registry, Pi warns about it, skips that package&#39;s resources, and keeps running. Pi tries to install it again on the next start or <code>/reload</code>. <code>pi install</code> and <code>pi update --extensions</code> still report the failure and exit non-zero.</p><p>Personal installs are written to <code>~/.pi/agent/settings.json</code>. Add <code>--local</code> or <code>-l</code> to write the package declaration to <code>.pi/settings.json</code>. Pi reads declarations from that file only after project trust is granted.</p><p>Project packages are installed and loaded only after project trust is resolved. Packages can execute extension code and can include skills that instruct the model to run programs. Review third-party package source before installing it. Review project package declarations before granting project trust.</p><p>Use <code>--extension</code> or <code>-e</code> to try a package for one invocation without adding it to settings:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm:@example/pi-tools</span></span></code></pre></div><h2 id="choose-a-source" tabindex="-1">Choose a source <a class="header-anchor" href="#choose-a-source" aria-label="Permalink to &quot;Choose a source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source</th><th>Example</th><th>Behavior</th></tr></thead><tbody><tr><td>npm</td><td><code>npm:@example/pi-tools@1.0.0</code></td><td>Installed under the Pi npm directory</td></tr><tr><td>git</td><td><code>git:github.com/example/pi-tools@v1</code></td><td>Cloned and reconciled to the selected ref</td></tr><tr><td>URL</td><td><code>https://github.com/example/pi-tools</code></td><td>Treated as a git source</td></tr><tr><td>Local</td><td><code>./pi-tools</code></td><td>Loaded from the resolved path without copying</td></tr></tbody></table><p>Versioned npm specifications are pinned. Git tags and commits are also pinned; package updates reconcile the checkout but do not move a configured ref.</p><p>Relative local paths resolve from the settings file that contains them. A file path loads one extension. A directory follows normal package discovery rules.</p><h2 id="create-a-package" tabindex="-1">Create a package <a class="header-anchor" href="#create-a-package" aria-label="Permalink to &quot;Create a package&quot;">​</a></h2><p>The simplest package uses conventional directories:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-pi-package/</span></span>
<span class="line"><span>├── package.json</span></span>
<span class="line"><span>├── extensions/</span></span>
<span class="line"><span>├── skills/</span></span>
<span class="line"><span>├── prompts/</span></span>
<span class="line"><span>└── themes/</span></span></code></pre></div><p>Without a <code>pi</code> manifest, Pi discovers TypeScript and JavaScript extensions, skill directories, Markdown prompts, and JSON themes from those directories.</p><p>Use an explicit manifest when resources live elsewhere or need filtering:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-pi-package&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;keywords&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pi-package&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;pi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;extensions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./src/extension.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;skills&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./resources/skills&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;prompts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./resources/prompts/*.md&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;themes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./resources/themes/*.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Paths are relative to the package root. Arrays accept glob patterns and exclusions. List dot-prefixed or symlinked resource roots directly when traversal through a glob would not discover them.</p><p>The <code>pi-package</code> keyword makes an npm package eligible for discovery in the <a href="https://pi.dev/packages" target="_blank" rel="noreferrer">Pi package gallery</a>. Optional <code>pi.image</code> and <code>pi.video</code> fields add gallery previews.</p><h2 id="declare-dependencies" tabindex="-1">Declare dependencies <a class="header-anchor" href="#declare-dependencies" aria-label="Permalink to &quot;Declare dependencies&quot;">​</a></h2><p>Put runtime packages imported by extensions in <code>dependencies</code>. Pi installs package dependencies when it installs an npm or git source.</p><p>Pi supplies these packages to extensions and skills:</p><ul><li><code>@earendil-works/pi-ai</code></li><li><code>@earendil-works/pi-agent-core</code></li><li><code>@earendil-works/pi-coding-agent</code></li><li><code>@earendil-works/pi-tui</code></li><li><code>typebox</code></li></ul><p>Declare the host-provided packages listed above in <code>peerDependencies</code> with a <code>&quot;*&quot;</code> range and do not bundle them. Pi suppresses automatic peer installation for managed npm packages and git packages installed with npm, pnpm, or Bun. Local packages are not installed or modified, so their dependency tree remains the package author&#39;s responsibility.</p><p>Do not list host-provided packages in <code>dependencies</code>. A physical copy can bypass Pi&#39;s extension module mapping in compiled ESM and create duplicate classes, registries, and initialization work. Pi reports an extension warning when it detects this manifest configuration. Other Pi packages used as dependencies must be included in the published tarball and referenced through their <code>node_modules</code> resource paths.</p><p>Installed packages load with separate module roots. Do not rely on two packages sharing one dependency instance or one package resolving another package’s undeclared dependency.</p><h2 id="select-package-resources" tabindex="-1">Select package resources <a class="header-anchor" href="#select-package-resources" aria-label="Permalink to &quot;Select package resources&quot;">​</a></h2><p>The object form in settings narrows which resources load from a package:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;packages&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;source&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;npm:@example/pi-tools&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;extensions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;extensions/*.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;!extensions/legacy.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;skills&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;prompts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;prompts/review.md&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>For each resource type:</p><ul><li>Omit the property to load everything allowed by the package.</li><li>Use <code>[]</code> to load none of that type.</li><li>Use <code>!pattern</code> to exclude glob matches.</li><li>Use <code>+path</code> to include one exact allowed path.</li><li>Use <code>-path</code> to exclude one exact path.</li></ul><p>Filters narrow the package manifest. They do not expose resources that the package itself did not declare.</p><p>Run <code>pi config</code> to enable or disable discovered resources and pi&#39;s built-in extensions. It starts with personal configuration; press Tab to switch scope, or run <code>pi config --local</code> to start with project overrides.</p><h2 id="understand-scope-and-identity" tabindex="-1">Understand scope and identity <a class="header-anchor" href="#understand-scope-and-identity" aria-label="Permalink to &quot;Understand scope and identity&quot;">​</a></h2><p>The same package can appear in personal and project settings. A project entry normally replaces the personal entry. With <code>autoload: false</code>, the project entry instead acts as a filtering delta over the personal package.</p><p>Pi identifies npm packages by package name, git packages by repository URL without the ref, and local packages by resolved absolute path. This prevents the same package from loading twice through equivalent declarations.</p><p>Use <a href="./extensions.html">Extensions</a>, <a href="./skills.html">Skills</a>, <a href="./prompt-templates.html">Prompt Templates</a>, and <a href="./themes.html">Themes</a> to design each resource before packaging it.</p>`,42)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
